function hurtEnemy(e,amount,source='Rift Slash'){if(!e.alive)return;e.hp-=amount;e.group.userData.flash=0.1;e.hpFill.scale.x=Math.max(.02,e.hp/e.max);e.hpFill.position.x=-(.68*(1-e.hp/e.max))/2;feed(`<b>${source}</b> · ${Math.round(amount)} damage`);if(state.sockets.some(Boolean)&&Math.random()<.25){const rune=state.sockets.find(Boolean);if(rune?.effect==='scorch'){e.hp-=4;feed('Ashen Rune · <b>scorch</b>','damage');}}if(e.hp<=0)killEnemy(e);}
function killEnemy(e){e.alive=false;arena.remove(e.group);state.kills++;state.shards+=5+Math.floor(Math.random()*5);if(Math.random()<.45)state.ember++;addXP(34);feed(`<b>${e.kind==='wraith'?'Veil wraith':e.kind==='brute'?'Cinder brute':'Ashling'} defeated</b> · +shards`,'good');if(state.kills%3===0){const drops=[item('Cinder Ore','Material','common','⬡','Useful ore, still warm from the deep.',{qty:2}),item('Ashen Rune','Rune','uncommon','◈','Socket: attacks scorch enemies for 4 damage.',{effect:'scorch'}),item('Veilguard Mantle','Armor','rare','⛨','Light armor woven with a wraith’s last breath. +22 vitality',{bonus:22}),item('Gloam Shard','Artifact','epic','✦','A fragment of the first eclipse. Its song is not yours alone.',{bonus:12})];const drop=drops[Math.floor(Math.random()*drops.length)];state.inventory.push(drop);feed(`Found <b>${drop.name}</b> · ${drop.rarity}`,'good');}updateEnemyCount();refreshHud();if(!enemies.some(x=>x.alive)){state.wave++;setTimeout(()=>{if(state.started){spawnWave(Math.min(3+state.wave,7));toast(`WAVE ${state.wave} · HOSTILES APPROACH`);}},2200);}}
function nearestEnemy(max=5){let best=null,d=max;for(const e of enemies){if(!e.alive)continue;const n=e.group.position.distanceTo(player.position);if(n<d){best=e;d=n;}}return best;}
function castAbility(n){if(!state.started)return;if(state.cooldowns[n-1]>0){toast('ABILITY RECHARGING');return;}const target=nearestEnemy(n===3?8:n===4?12:5);if(n===1){if(!target){toast('NO HOSTILE IN RANGE');return;}hurtEnemy(target,state.weaponPower+(state.level-1)*3,'Rift Slash');state.cooldowns[0]=.55;heroBody.rotation.y=Math.atan2(target.group.position.x-player.position.x,target.group.position.z-player.position.z);}
if(n===2){if(state.mana<18){toast('NOT ENOUGH ESSENCE');return;}state.mana-=18;state.ward=4;state.hp=Math.min(state.maxHp,state.hp+10);state.cooldowns[1]=7;feed('<b>Veil Ward</b> · damage absorbed','good');refreshHud();}
if(n===3){if(state.mana<28){toast('NOT ENOUGH ESSENCE');return;}state.mana-=28;state.cooldowns[2]=9;const nearby=enemies.filter(e=>e.alive&&e.group.position.distanceTo(player.position)<8);if(!nearby.length)toast('EMBER NOVA · NO HOSTILES NEAR');nearby.forEach(e=>hurtEnemy(e,37+(state.level-1)*4,'Ember Nova'));burst(player.position.x,player.position.z,'#ff9b59');refreshHud();}
if(n===4){if(state.mana<55){toast('NOT ENOUGH ESSENCE');return;}state.mana-=55;state.cooldowns[3]=16;const nearby=enemies.filter(e=>e.alive&&e.group.position.distanceTo(player.position)<12);nearby.forEach(e=>hurtEnemy(e,75+(state.level-1)*8,'Divine Wrath'));burst(player.position.x,player.position.z,state.faction==='demon'?'#d15852':'#f6d38e');if(nearby.length)feed('<b>DIVINE WRATH</b> · the veil recoils','good');refreshHud();}
$$(`[data-ability="${n}"]`).forEach(el=>{el.classList.add('active');setTimeout(()=>el.classList.remove('active'),200);});}
function burst(x,z,color){const m=new THREE.MeshBasicMaterial({color,transparent:true,opacity:.8,side:THREE.DoubleSide});const ring=new THREE.Mesh(new THREE.RingGeometry(.5,.8,40),m);ring.rotation.x=-Math.PI/2;ring.position.set(x,.12,z);fxGroup.add(ring);const start=performance.now();const tick=()=>{const t=(performance.now()-start)/700;if(t>=1){fxGroup.remove(ring);ring.geometry.dispose();m.dispose();return;}ring.scale.setScalar(1+t*10);m.opacity=.8*(1-t);requestAnimationFrame(tick);};tick();}
$$('.ability,.mobile-actions button').forEach(el=>el.addEventListener('click',()=>castAbility(Number(el.dataset.ability))));
function startGame(faction){setFaction(faction);state.started=true;$('#start-screen').classList.remove('open');toast(faction==='demon'?'THE ABYSSAL COURT REMEMBERS':'THE RADIANT HOST REMEMBERS');setTimeout(()=>feed('Ashen Watch · <b>3 hostiles</b> remain','damage'),1200);}
