let inventoryFilter='All';
function openPanel(type){const scrim=$('#panel-scrim');scrim.classList.add('open');renderPanel(type);}
function closePanel(){$('#panel-scrim').classList.remove('open');}
$('#panel-close').addEventListener('click',closePanel);$('#panel-scrim').addEventListener('click',e=>{if(e.target.id==='panel-scrim')closePanel();});$$('.quick-nav button').forEach(b=>b.addEventListener('click',()=>openPanel(b.dataset.panel)));
function panelHeading(kicker,title,intro=''){return `<div class="panel-eyebrow">${kicker}</div><h2>${title}</h2><p class="panel-intro">${intro}</p>`;}
function renderPanel(type){const root=$('#panel-content');if(type==='inventory'){const types=['All','Weapon','Armor','Artifact','Rune','Material','Consumable'];const list=state.inventory.filter(it=>inventoryFilter==='All'||it.type===inventoryFilter);const eligible=[...new Set(state.inventory.filter(i=>['Weapon','Armor','Artifact','Rune'].includes(i.type)).map(i=>i.name))].filter(name=>state.inventory.filter(i=>i.name===name).length>=3);root.innerHTML=panelHeading('YOUR RELICS · FIELD KIT','Inventory','Gear, artifacts, and fragments recovered from the Shattered Veil.')+`<div class="panel-tabs">${types.map(t=>`<button data-filter="${t}" class="${inventoryFilter===t?'selected':''}">${t.toUpperCase()}</button>`).join('')}</div><div class="item-grid">${list.length?list.map(it=>`<article class="item-card"><span class="rarity ${it.rarity.toLowerCase()}">${it.rarity}</span><div class="item-icon">${it.icon}</div><b>${it.name}${it.qty>1?` ×${it.qty}`:''}</b><small>${it.type.toUpperCase()} ${it.equipped?'· EQUIPPED':''}</small><p>${it.desc}</p>${['Weapon','Armor','Artifact'].includes(it.type)?`<button class="action-btn item-action" data-action="equip" data-id="${it.id}">${it.equipped?'EQUIPPED':'EQUIP'}</button>`:it.type==='Consumable'?`<button class="action-btn item-action" data-action="use" data-id="${it.id}">USE</button>`:''}</article>`).join(''):'<p class="panel-intro">No relics in this category yet.</p>'}</div><div class="panel-actions"><button class="action-btn" data-action="merge" ${eligible.length?'':'disabled'}>✧ MERGE DUPLICATES (${eligible.length})</button><button class="action-btn" data-action="sort">SORT BY RARITY</button></div>`;}
if(type==='forge'){root.innerHTML=panelHeading('BLACKSMITH · CINDER FORGE','The Blacksmith','Spend field resources to temper your weapon, forge runes, and bind a rune into your blade.')+`<div class="forge-layout"><div class="forge-box"><h3>Temper your weapon</h3><div class="forge-feature"><i>⚔</i><div><b>${state.gear.weapon}</b><small>POWER ${state.weaponPower} · ${state.weaponRarity.toUpperCase()}</small></div></div><p>Reinforce the edge with ember and cinder ore. Each temper adds <b>+6 attack</b>.</p><div class="cost">COST · 12 SHARDS · 2 EMBER · 2 CINDER ORE</div><div class="panel-actions"><button class="action-btn" data-action="upgrade">⚒ TEMPER WEAPON</button></div></div><div class="forge-box"><h3>Bind a rune</h3><p>Click a socket to remove its rune, or bind an unspent rune from your inventory.</p><div class="rune-slots">${state.sockets.map((r,i)=>`<button class="rune-slot ${r?'filled':''}" data-action="socket" data-slot="${i}" title="${r?`Remove ${r.name}`:'Choose rune'}">${r?r.icon:'+'}</button>`).join('')}</div><div class="panel-actions"><button class="action-btn" data-action="bind-rune">◈ SELECT RUNE</button><button class="action-btn" data-action="craft-rune">✧ FORGE ASHEN RUNE</button></div><div class="cost">RUNE RECIPE · 8 SHARDS · 2 EMBER · 1 CINDER ORE</div></div><div class="forge-box"><h3>Fieldcraft</h3><p>Bind moonpetals with ember to distill a restorative flask.</p><div class="cost">COST · 4 SHARDS · 1 MOONPETAL</div><div class="panel-actions"><button class="action-btn" data-action="craft-flask">♜ CRAFT MINOR FLASK</button></div></div><div class="forge-box"><h3>Materials</h3><p>Shards <b>${state.shards}</b> · Ember <b>${state.ember}</b> · Cinder Ore <b>${materialCount('Cinder Ore')}</b> · Moonpetal <b>${materialCount('Moonpetal')}</b></p><div class="cost">Explore, fight, and claim drops to gather more.</div></div></div>`;}
if(type==='story'){root.innerHTML=storyMarkup();}
if(type==='codex'){root.innerHTML=panelHeading('FIELD GUIDE · VEIL ARCHIVES','Codex','Survive the borderlands. Learn what the old factions left behind.')+`<div class="codex-list"><div class="codex-entry"><b>ASHLINGS · COMMON HOSTILE</b><p>Remnants of the fallen watch. They hunt by warmth and gather in packs. Defeat them for shards and experience.</p></div><div class="codex-entry"><b>THE VEIL ALTAR · STORY</b><p>A broken shrine at the heart of the borderlands. The Veilkeeper remembers your choices. Approach it and press E.</p></div><div class="codex-entry"><b>MERGING · RELIC CRAFT</b><p>Three identical weapons, armor pieces, artifacts, or runes may be merged into one relic of the next rarity.</p></div><div class="codex-entry"><b>RUNE SOCKETS · BLACKSMITH</b><p>Runes carry persistent effects. Bind them to your weapon at the Cinder Forge to change your attacks.</p></div><div class="codex-entry"><b>CONTROLS</b><p>WASD / arrows to move · 1–4 or tap combat arts · E interact · I inventory · F forge · J chronicle.</p></div></div>`;}
root.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{inventoryFilter=b.dataset.filter;renderPanel('inventory');}));root.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>handlePanelAction(b.dataset.action,b.dataset.id,b.dataset.slot,type)));
}
function materialCount(name){return state.inventory.filter(i=>i.name===name).reduce((n,i)=>n+i.qty,0);}
function consumeMaterial(name,n){let left=n;for(const it of state.inventory.filter(i=>i.name===name)){const take=Math.min(left,it.qty);it.qty-=take;left-=take;if(it.qty<=0)state.inventory.splice(state.inventory.indexOf(it),1);if(!left)break;}return left===0;}
function handlePanelAction(action,id,slot,type){if(action==='equip'){const it=state.inventory.find(x=>x.id===id);if(!it)return;state.inventory.filter(x=>x.type===it.type).forEach(x=>x.equipped=false);it.equipped=true;if(it.type==='Weapon'){state.gear.weapon=it.name;state.weaponPower=it.power||18;state.weaponRarity=it.rarity;$('#weapon-label').innerHTML=`${it.name} <i>✦</i>`;$('#weapon-type').textContent=`${it.type.toUpperCase()} · ${it.rarity.toUpperCase()}`;}if(it.type==='Armor'){state.maxHp=100+(it.bonus||0);state.hp=Math.min(state.maxHp,state.hp+8);refreshHud();}if(it.type==='Artifact'){state.gear.artifact=it.name;}toast(`${it.name.toUpperCase()} EQUIPPED`);renderPanel(type);}
if(action==='use'){const it=state.inventory.find(x=>x.id===id);if(it&&it.type==='Consumable'){state.hp=Math.min(state.maxHp,state.hp+35);it.qty--;if(it.qty<=0)state.inventory.splice(state.inventory.indexOf(it),1);refreshHud();toast('35 VITALITY RESTORED');renderPanel(type);}}
